```
function isSevereSymptom(severity) {
  return severity >= 7;
}

function formatSymptomLog(symptom, severity, isSevere) {
  return `${symptom}: ${severity}${isSevere ? " (SEVERE)" : ""}`;
}

function saveSymptomEntry(entry) {
